# بدون queryset — basename اجباری
class MyBookViewSet(viewsets.ModelViewSet):
    serializer_class = BookSerializer
    # queryset تعریف نشده — فقط get_queryset

    def get_queryset(self):
        return Book.objects.filter(owner=self.request.user)

router.register(r"my-books", MyBookViewSet, basename="my-book")

class ReviewViewSet(viewsets.ModelViewSet):
    serializer_class = ReviewSerializer

    def get_queryset(self):
        return Review.objects.filter(book_id=self.kwargs["book_pk"])

    def perform_create(self, serializer):
        serializer.save(
            book_id=self.kwargs["book_pk"],
            user=self.request.user,
        )

class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.all()
    serializer_class = BookSerializer

    def published(self, request):
        books = self.get_queryset().filter(is_published=True)
        serializer = self.get_serializer(books, many=True)
        return Response(serializer.data)

from rest_framework.decorators import api_view
from rest_framework.response import Response
from rest_framework.reverse import reverse


@api_view(["GET"])
def api_root(request, format=None):
    return Response({
        "books": reverse("book-list", request=request, format=format),
        "categories": reverse("category-list", request=request, format=format),
        "docs": "/api/docs/",
    })
